cat > /tmp/sha1_verify.mjs <<'EOF'
import { sha1, sha1Hex } from '/output/hash/sha1.mjs';

const enc = new TextEncoder();
const cases = [
  ['', 'da39a3ee5e6b4b0d3255bfef95601890afd80709'],
  ['abc', 'a9993e364706816aba3e25717850c26c9cd0d89d'],
  ['abcdbcdecdefdefgefghfghighijhijkijkljklmklmnlmnomnopnopq', '84983e441c3bd26ebaae4aa1f95129e5e54670f1'],
  ['a'.repeat(1000000), '34aa973cd4c4daa4f61eeb2bdbad27316534016f'],
  // boundary lengths around 55/56/64/119/120 bytes
  ['a'.repeat(55), null], ['a'.repeat(56), null],
  ['a'.repeat(63), null], ['a'.repeat(64), null], ['a'.repeat(65), null],
  ['a'.repeat(119), null], ['a'.repeat(120), null],
];
let fail = 0;
for (const [input, expected] of cases) {
  const got = sha1Hex(enc.encode(input));
  if (expected !== null) {
    if (got !== expected) { console.log(`FAIL len=${input.length}: ${got} != ${expected}`); fail++; }
    else console.log(`ok len=${input.length}`);
  } else {
    console.log(`len=${input.length}: ${got}`);
  }
}
// also check sha1 returns Uint8Array of 20 bytes
const d = sha1(enc.encode('abc'));
console.log('digest is Uint8Array(20):', d instanceof Uint8Array && d.length === 20);
process.exit(fail ? 1 : 0);
EOF
node /tmp/sha1_verify.mjs
